  B: ["cauldron", {}],
  D: ["dispenser", { facing: "west" }],
  K: ["barrel", { facing: "up" }],
  // light: lanterns hang at y4 from chains off the ceiling
  L: ["lantern", { hanging: "true" }],
  C: ["iron_chain", { axis: "y" }],
};

export function build(g) {
  // rows run along +x (x 30, 31), successive rows along +z (z 25..28); '.' is left as it is (air)
